export const DOC_MARKER = '<!-- generated by comb';
const STAMPED_RE = /^<!-- generated by comb from (sha256:[0-9a-f]{16}); edit the specs, not this file -->$/;
const WRITTEN_RE = /^<!-- generated by comb for (sha256:[0-9a-f]{16}) -->$/;

const firstLine = (text: string): string => {
  const nl = text.indexOf('\n');
  return (nl < 0 ? text : text.slice(0, nl)).trimEnd();
};

/**
 * A generated document starts with a marker. The agent writes `<!-- generated by comb for <hash> -->` with the source
 * hash `comb instructions docs` gave it (`writtenFor`); `comb docs stamp` turns that into the stamped header (`hash`)
 * only while the sources still have that hash. Any other marker line is generated but neither.
 */
export function docHeader(text: string): { generated: boolean; hash: string | null; writtenFor: string | null } {
  const first = firstLine(text);
  if (!first.startsWith(DOC_MARKER)) return { generated: false, hash: null, writtenFor: null };
  return { generated: true, hash: STAMPED_RE.exec(first)?.[1] ?? null, writtenFor: WRITTEN_RE.exec(first)?.[1] ?? null };
}

/** The first line the agent writes, for the sources it was given. */
export const writtenMarker = (hash: string): string => `<!-- generated by comb for ${hash} -->`;

export const stampedHeader = (hash: string): string => `<!-- generated by comb from ${hash}; edit the specs, not this file -->`;

/** Replaces the first line (the marker) with the stamped header. */
export function stampDoc(text: string, hash: string): string {
  const nl = text.indexOf('\n');
  return `${stampedHeader(hash)}${nl < 0 ? '\n' : text.slice(nl)}`;
}
